def restore_ip_addresses(digits):
    n = len(digits)
    results = []

    def valid(seg):
        if len(seg) > 1 and seg[0] == "0":
            return False
        return int(seg) <= 255

    def backtrack(start, parts):
        if len(parts) == 4:
            if start == n:
                results.append(".".join(parts))
            return
        remaining = 4 - len(parts)
        if n - start < remaining or n - start > remaining * 3:
            return
        for length in range(1, 4):
            if start + length > n:
                break
            seg = digits[start:start + length]
            if valid(seg):
                parts.append(seg)
                backtrack(start + length, parts)
                parts.pop()

    backtrack(0, [])
    results.sort()
    return results
